#include <iostream>
using namespace std;

int main() {
    char name[4] = "Ali";
    int len = 0;
    while (name[len] != '\0') {
        cout << name[len] << " = " << (int)name[len] << endl;
        len++;
    }
    cout << "Length = " << len << endl;
    return 0;
}

#include <iostream>
#include <cctype>
using namespace std;

int main() {
    char full[30];
    cout << "Enter full name: ";
    cin.getline(full, 30);
    int len = 0;
    int vowels = 0;
    for (int i = 0; full[i] != '\0'; i++) {
        len++;
        char ch = tolower(full[i]);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            vowels++;
        }
    }
    cout << "Welcome, " << full << endl;
    cout << "Length = " << len << endl;
    cout << "Vowels = " << vowels << endl;
    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char first[20] = "Ali";
    char last[20] = "Khan";
    char full[40];
    strcpy(full, first);
    strcat(full, " ");
    strcat(full, last);
    cout << full << endl;
    cout << strlen(full) << endl;
    if (strcmp(first, last) == 0) {
        cout << "Same" << endl;
    } else {
        cout << "Different" << endl;
    }
    return 0;
}

