#include <iostream>
using namespace std;
int main() {
    char w[30];
    cin >> w;
    int len = 0;
    while (w[len] != '\0') {
        len++;
    }
    for (int i = len - 1; i >= 0; i--) {
        cout << w[i];
    }
    cout << endl;
    return 0;
}
